1	interface Item {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	}
6	
7	interface QuoteStep {
8	  op: "quote";
9	  items: Item[];
10	}
11	
12	interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	interface ClaimStep {
18	  op: "claim";
19	  policy: number;
20	  incident: { cause: string; damages: Damage[] };
21	}
22	
23	type Step = QuoteStep | ClaimStep;
24	
25	interface Scenario {
26	  customer: { yearsWithMHPCO: number };
27	  steps: Step[];
28	}
29	
30	interface QuoteResult {
31	  premium: number;
32	}
33	
34	interface ClaimResult {
35	  payout: number;
36	  remainingCap: number;
37	}
38	
39	type StepResult = QuoteResult | ClaimResult;
40	
41	const BASE_PREMIUM: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	};
48	
49	const PROCESSING_FEE = 5;
50	const FIRST_INSURANCE_SURCHARGE = 0.1;
51	
52	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
53	const COMPONENT_UNIT_PREMIUM = 25;
54	const COMPONENT_BLOCK_SIZE = 3;
55	const COMPONENT_BLOCK_PREMIUM = 60;
56	
57	const componentGroupBase = (count: number): number =>
58	  count === COMPONENT_BLOCK_SIZE
59	    ? COMPONENT_BLOCK_PREMIUM
60	    : count * COMPONENT_UNIT_PREMIUM;
61	
62	const componentsBase = (components: Item[]): number => {
63	  const countsByType = new Map<string, number>();
64	  for (const component of components) {
65	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
66	  }
67	  return [...countsByType.values()].reduce(
68	    (total, count) => total + componentGroupBase(count),
69	    0,
70	  );
71	};
72	
73	const isComponent = (item: Item): boolean =>
74	  COMPONENT_TYPES.has(item.type);
75	
76	const itemsBase = (items: Item[]): number => {
77	  const mainBase = items
78	    .filter((item) => !isComponent(item))
79	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
80	  return mainBase + componentsBase(items.filter(isComponent));
81	};
82	
83	const CURSE_SURCHARGE = 0.5;
84	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
86	
87	// Sum `rate * base premium` for every item matching `applies`. The additive
88	// per-item form keeps each surcharge a flat term so quotePremium stays additive
89	// (see the float-drift note there).
90	const itemSurcharge = (
91	  items: Item[],
92	  applies: (item: Item) => boolean,
93	  rate: number,
94	): number =>
95	  items.reduce(
96	    (sum, item) => sum + (applies(item) ? BASE_PREMIUM[item.type] * rate : 0),
97	    0,
98	  );
99	
100	const curseSurcharge = (items: Item[]): number =>
101	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE);
102	
103	const highEnchantmentSurcharge = (items: Item[]): number =>
104	  itemSurcharge(
105	    items,
106	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
107	    HIGH_ENCHANTMENT_SURCHARGE,
108	  );
109	
110	const LOYALTY_DISCOUNT = 0.2;
111	const LOYALTY_THRESHOLD_YEARS = 2;
112	const FOLLOWUP_DISCOUNT = 0.15;
113	
114	const loyaltyDiscount = (base: number, yearsWithMHPCO: number): number =>
115	  yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? base * LOYALTY_DISCOUNT : 0;
116	
117	const followupDiscount = (base: number, isFollowup: boolean): number =>
118	  isFollowup ? base * FOLLOWUP_DISCOUNT : 0;
119	
120	// Always-on surcharge charged on every policy, expressed as a flat term so
121	// quotePremium stays additive (see the float-drift note there).
122	const firstInsuranceSurcharge = (base: number): number =>
123	  base * FIRST_INSURANCE_SURCHARGE;
124	
125	const isKnownType = (type: string): boolean => type in INSURANCE_VALUE;
126	
127	const assertKnownItems = (items: Item[]): void => {
128	  for (const item of items) {
129	    if (!isKnownType(item.type)) {
130	      throw new Error(`Unknown item type: ${item.type}`);
131	    }
132	  }
133	};
134	
135	const quotePremium = (
136	  items: Item[],
137	  yearsWithMHPCO: number,
138	  isFollowup: boolean,
139	): number => {
140	  assertKnownItems(items);
141	  const base = itemsBase(items);
142	  const surcharges =
143	    firstInsuranceSurcharge(base) +
144	    curseSurcharge(items) +
145	    highEnchantmentSurcharge(items);
146	  const discounts =
147	    loyaltyDiscount(base, yearsWithMHPCO) + followupDiscount(base, isFollowup);
148	  // Sum flat terms rather than scaling `base * (1 + rate)`: the additive form
149	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
150	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
151	};
152	
153	const DEDUCTIBLE = 100;
154	const CAP_MULTIPLIER = 2;
155	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
156	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
157	
158	const INSURANCE_VALUE: Record<string, number> = {
159	  sword: 1000,
160	  amulet: 600,
161	  staff: 800,
162	  potion: 400,
163	  rune: 250,
164	  moonstone: 250,
165	};
166	
167	const insuranceSum = (items: Item[]): number =>
168	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
169	
170	// Reimbursement for a single damage before the deductible. Items enchanted to
171	// level 8+ are reimbursed at only 50% of the damage amount.
172	const reimbursement = (item: Item, amount: number): number =>
173	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
174	    ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT
175	    : amount;
176	
177	// The policy item a damage refers to, matched by type. Damages are assumed to
178	// reference a covered item (validation of unknown items is a later concern).
179	const policyItemFor = (damage: Damage, policyItems: Item[]): Item =>
180	  policyItems.find((item) => item.type === damage.itemType) as Item;
181	
182	// Each damaged item is reimbursed (subject to clauses) less one deductible,
183	// floored in MHPCO's favor.
184	const damagesPayout = (damages: Damage[], policyItems: Item[]): number =>
185	  Math.floor(
186	    damages.reduce((sum, damage) => {
187	      const item = policyItemFor(damage, policyItems);
188	      return sum + (reimbursement(item, damage.amount) - DEDUCTIBLE);
189	    }, 0),
190	  );
191	
192	const claimResult = (
193	  claim: ClaimStep,
194	  policyItems: Item[],
195	  remainingCap: number,
196	): ClaimResult => {
197	  const desired = damagesPayout(claim.incident.damages, policyItems);
198	  const payout = Math.min(desired, remainingCap);
199	  return { payout, remainingCap: remainingCap - payout };
200	};
201	
202	// A policy's cap starts at twice its insurance sum and is drawn down by each
203	// claim. remainingCapByPolicy tracks the running balance keyed by policy step
204	// index, seeding the initial cap the first time a policy is claimed against.
205	const settleClaim = (
206	  claim: ClaimStep,
207	  steps: Step[],
208	  remainingCapByPolicy: Map<number, number>,
209	): ClaimResult => {
210	  const policyItems = (steps[claim.policy] as QuoteStep).items;
211	  const remainingCap =
212	    remainingCapByPolicy.get(claim.policy) ??
213	    CAP_MULTIPLIER * insuranceSum(policyItems);
214	  const result = claimResult(claim, policyItems, remainingCap);
215	  remainingCapByPolicy.set(claim.policy, result.remainingCap);
216	  return result;
217	};
218	
219	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
220	  const remainingCapByPolicy = new Map<number, number>();
221	  const results = scenario.steps.map((step, index): StepResult => {
222	    if (step.op === "claim") {
223	      return settleClaim(step, scenario.steps, remainingCapByPolicy);
224	    }
225	    // Every quote after the first is a follow-up contract; the map index is
226	    // already the count of quotes seen so far, so no separate counter is needed.
227	    const isFollowup = index > 0;
228	    return {
229	      premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, isFollowup),
230	    };
231	  });
232	  return { results };
233	};
